import{C as a,c as r}from"./dom-6kYVTdCz.js";function I(){const t={fn:a("--c-accent"),n:a("--c-n"),s:a("--c-s"),f:a("--c-f"),pos:[a("--pos-1"),a("--pos-2"),a("--pos-3"),a("--pos-4")],sh:a("--pos-sh"),warn:a("--warn"),crit:a("--crit"),ink:a("--ink"),ink2:a("--ink-2"),muted:a("--muted"),grid:a("--grid"),axis:a("--axis"),surface:a("--surface")},l=[{key:"dominant",name:"Dominant",sub:"1st · hero",types:"INFP · ISFP",shadow:!1,series:0,params:{scale:1,fidelity:.95,latency:0,noise:0,duty:1,control:1,contrary:0},text:"The world is measured against an inner tone. Conviction is effortless and constant — not argued, simply known. The core burns steady; the hierarchy of what matters is deep, calm, and exact."},{key:"auxiliary",name:"Auxiliary",sub:"2nd · parent",types:"ENFP · ESFP",shadow:!1,series:1,params:{scale:.8,fidelity:.85,latency:80,noise:.05,duty:.85,control:.9,contrary:0},text:'The compass behind the explorer. Fi here vets what the dominant perceiver drags home — "is this us? could I live with this?" — quiet in the background, decisive at exactly the moments that matter.'},{key:"tertiary",name:"Tertiary",sub:"3rd · eternal child",types:"ISTJ · INTJ",shadow:!1,series:2,params:{scale:.55,fidelity:.6,latency:250,noise:.2,duty:.5,control:.6,contrary:0},text:'A private moral sense, real but narrow — fierce loyalty to a few people and principles, guarded like contraband and dismissed in public as "just being practical". It blooms, quietly, with age.'},{key:"inferior",name:"Inferior",sub:"4th · aspirational",types:"ESTJ · ENTJ",shadow:!1,series:3,params:{scale:.4,fidelity:.35,latency:700,noise:.45,duty:.25,control:.35,contrary:0},text:`Feeling arrives late and off-balance. Long stretches of "emotions are noise in the data", punctuated — under stress — by waves of wounded, moralizing sentiment that don't sound like them at all.`},{key:"opposing",name:"Opposing",sub:"5th · shadow",types:"ENFJ · ESFJ",shadow:!0,series:4,params:{scale:.46,fidelity:.42,latency:600,noise:.5,duty:.45,control:.4,contrary:.25},text:`The stubborn conscience. When their Fe harmonizing is challenged, Fi wakes up contrary — "I don't care what the room needs, this is where I stand" — protective, prickly, and briefly immovable.`},{key:"critical",name:"Critical Parent",sub:"6th · shadow",types:"INFJ · ISFJ",shadow:!0,series:4,params:{scale:.44,fidelity:.35,latency:900,noise:.55,duty:.35,control:.3,contrary:.35},text:'An inner voice that interrogates the heart: "do you even know what you want? your feelings are self-indulgent." Harsh, sporadic, and aimed mostly at the self.'},{key:"trickster",name:"Trickster",sub:"7th · shadow",types:"ESTP · ENTP",shadow:!0,series:4,params:{scale:.42,fidelity:.28,latency:1200,noise:.6,duty:.3,control:.2,contrary:.55},text:"Personal conviction as a trap to wriggle out of. Asked what they truly feel, this position deflects with charm or contrarian play — blind, without malice, to the difference between a value and a preference."},{key:"demon",name:"Demon",sub:"8th · shadow",types:"ISTP · INTP",shadow:!0,series:4,params:{scale:.4,fidelity:.2,latency:1500,noise:.65,duty:.22,control:.12,contrary:.65},text:"Rarely touched, and volcanic when it erupts: a conviction of worthlessness or betrayal so total it presents itself as objective fact — moral certainty aimed inward like a weapon."}],h={endurance:{w:1,why:"conviction is effortless and constant — the core burns without fuel"},precision:{w:.92,why:"the hierarchy of what matters is deep, calm, and exact"},speed:{w:.7,why:"deep and still — the verdict is total, and rarely fast"},control:{w:.9,why:"steerable up to the line a value draws; immovable past it"},awareness:{w:.97,why:"the most self-transparent seat in the stack: the tone is always audible"}},d=[{key:"ne",name:"Ne",color:t.n,canonical:!0,pair:"the INFP coupling",cfg:{rate:.36,branchy:.85,speed:.35,spread:.95,persistence:.35},text:"Moral imagination. Ne delivers forking possibilities, and each one is struck against the core — could I live with this? who would I be in that world? The hierarchy grows wide: many futures held lightly, waiting to see which ones ring true."},{key:"se",name:"Se",color:t.s,canonical:!0,pair:"the ISFP coupling",cfg:{rate:.58,branchy:0,speed:1,spread:.15,persistence:.95},text:"Embodied conviction. Se delivers the vivid, concrete present — Fi weighs what is actually here, now, in front of it. The hierarchy grows tight and lived-in: taste, beauty, and right-action felt in the hands rather than argued in the head."},{key:"si",name:"Si",color:"#c07f10",canonical:!1,pair:"the loop coupling (Fi–Si, INFP under stress)",cfg:{rate:.3,branchy:0,speed:.3,spread:.2,persistence:1},text:"Experience drawn from the archive rather than the world: old wounds and old kindnesses replayed against the core tone, verdicts re-felt instead of re-tested. Tender, airless, and increasingly detached from anything new — the visual signature of a cognitive loop."},{key:"ni",name:"Ni",color:"#7148d8",canonical:!1,pair:"a non-standard coupling",cfg:{rate:.15,branchy:.15,speed:.2,spread:.5,persistence:.7},text:"Speculative: a thin stream of pre-converged meaning. Fi receives few experiences but heavy ones — each arrival re-weighing the whole hierarchy at once. No standard stack places Ni directly above Fi."},{key:"te",name:"Te",color:"#3fb4c9",canonical:!1,unstable:!0,pair:"judging feeding judging",cfg:{rate:.12,branchy:0,speed:.3,spread:.4,persistence:.5},text:"Two sorters, no gatherer. Te hands Fi verdicts about efficiency rather than lived experience — the chamber idles hungry, with almost nothing arriving to weigh. This is why real stacks alternate perceiving and judging."}];function c(e){const F=20*Math.pow(e/60,1.25);let o=0;for(const[s,T]of[[16,8],[41,12],[68,9],[97,9]])e>=s&&(o+=T*r((e-s)/2,0,1));const x=e<2?0:1.6*Math.sin(e*.9)+1.2*Math.sin(e*2.3+1);return r(F+o+x,0,100)}const i=[{key:"dom",label:"Dominant",color:t.pos[0],f:e=>Math.max(0,13*(e/60)-2.2*Math.pow(Math.max(0,Math.sin(e/8.2)),3))},{key:"aux",label:"Auxiliary",color:t.pos[1],f:e=>21*Math.pow(e/60,1.08)},{key:"tert",label:"Tertiary",color:t.pos[2],f:e=>30*Math.pow(e/60,1.4)},{key:"inf",label:"Inferior",color:t.pos[3],f:e=>Math.min(100,82*Math.pow(e/60,1.9))},{key:"sh",label:"Shadow",color:t.sh,f:c}],u=60*Math.pow(100/82,1/1.9),f=[{label:"Dominant",v:1,color:t.pos[0],series:0},{label:"Auxiliary",v:1.5,color:t.pos[1],series:1},{label:"Tertiary",v:2.5,color:t.pos[2],series:2},{label:"Inferior",v:4,color:t.pos[3],series:3},{label:"Shadow",v:4.5,color:t.sh,band:[3,6],series:4}],p=[{label:"Dominant",color:t.pos[0],note:"Refills in minutes — and partially during use (flow).",f:e=>e<=30?100-i[0].f(e):n(0)+(100-n(0))*(1-Math.exp(-(e-30)/6))},{label:"Auxiliary",color:t.pos[1],note:"Quick, clean recovery.",f:e=>e<=30?100-i[1].f(e):n(1)+(100-n(1))*(1-Math.exp(-(e-30)/10))},{label:"Tertiary",color:t.pos[2],note:"A slower refill; rest must be deliberate.",f:e=>e<=30?100-i[2].f(e):n(2)+(100-n(2))*(1-Math.exp(-(e-30)/16))},{label:"Inferior",color:t.pos[3],note:"The hangover shelf: ~30 min where the whole system runs dim.",f:e=>e<=30?100-i[3].f(e):e<60?n(3):n(3)+(100-n(3))*(1-Math.exp(-(e-60)/20))},{label:"Shadow",color:t.sh,note:"Incomplete — some of the charge simply doesn't come back today.",f:e=>e<=30?100-i[4].f(e):n(4)+(93-n(4))*(1-Math.exp(-(e-30)/25))}];function n(e){return 100-i[e].f(30)}const y={buttons:[{id:"btnAuthGood",label:"Experience authentic joy",sub:"something true and resonant",color:"#f0b95c"},{id:"btnAuthBad",label:"Experience authentic grief",sub:"true, painful, held deeply",color:"#6272dd"},{id:"btnFakeGood",label:"Hear an inauthentic pleasantry",sub:"flattery glides off unabsorbed",color:"#ffd9e6"},{id:"btnFakeBad",label:"Witness an inauthentic violation",sub:"a falsehood tears the mist",color:t.crit}],narrations:{authGood:"Something joyful — and true — arrives. It rings against the core, diffuses deep into the nebula, and sets the mist gently turning. Pleasure blooms, and for a while the colour of the whole warms toward what was taken in.",authBad:"Something painful — and true. Fi does not flinch: the grief diffuses inward and the mist slows, darkens, and holds it. Stress rises, but so does resonance — this is not enjoyment, it is rightness. It, too, will colour the whole.",fakeGood:"Flattery arrives — pleasant, glossy, and hollow. The mist refuses to mix with it…",fakeGoodEnd:"…it glides along the inside of the chamber, dissolving nothing and being dissolved by nothing, is politely tolerated — and shown out exactly as it came. The nebula keeps none of it.",fakeBad:"A falsehood strikes what matters. It tears straight through the nebula — mist churns away from its path, a vacuum drags behind it —",fakeBadMid:"— and some of the mist bleeds out through the wound. The chamber red-shifts while everything attached to the wounded value finds a new place.",fakeBadEnd:"…the wound closes. The mist stills, the colour steadies — darker in places, rearranged in others. Fi keeps what was real, and remembers where it bled."}},g={tag:"introverted feeling",title:"Introverted Feeling",subtitle:"A quiet nebula around a core tone — weighing every experience against an unargued inner compass."},m={kicker:"Zone B · stack position",heading:"The Eight Faces of Fi",lede:"Click any position to see how the nebula changes — from the deep, steady conviction of a dominant to the volcanic, inward-facing moral certainty of the demon. Drag the maturity slider to watch the lower positions slowly gain fidelity with age."},w={kicker:"Zone C · feeder coupling",heading:"What Feeds Into Fi?",lede:"Every judging function needs a perceiving partner to deliver raw material. Click a feeder to watch how the nebula changes shape and motion."},b={kicker:"Zone D · verification lab",heading:"The Verification Lab",lede:"Watch Fi weigh experiences against its core tone in real time. Each button triggers a different lifecycle event inside the nebula."},v={kicker:"Zone E · energy economics",heading:"Energy Economics",lede:"Every invocation of Fi costs energy. The lower it sits in the stack, the more expensive it becomes — and the faster the battery drains."},k={kicker:"Zone E · field notes",heading:"Field Notes",lede:"Patterns from the wild — how Fi shows up in daily life.",mirror:{label:"Fi",counterpart:"Fe",counterpartColor:t.f,html:"Where <strong>Fe</strong> reads the emotional tone of the room and builds social harmony, <strong>Fi</strong> reads the emotional tone of the self and builds personal integrity. Fe trades individual preference for group unity; Fi trades group approval for internal truth."},vignettes:[{kind:"field sighting",title:"The Silent Compass",text:'An INFP sits quietly in a meeting where everyone agrees on a compromise. Suddenly they say "no" — not loudly, not with a ten-point argument, but with an absolute firmness that stops the room.'},{kind:"the loop",title:"The Loop",text:"Under stress, INFP Fi pairs with tertiary Si: replaying old wounds and old kindnesses against the core tone, re-feeling verdicts instead of re-testing them. Tender, airless, and detached from anything new."},{kind:"the grip",title:"The Inferior Eruption",text:"An ESTJ under stress suddenly breaks down into overwhelming, wounded moralizing — accusing others of betrayal and heartlessness with an intensity that startles everyone."},{kind:"as a tertiary",title:"The Locked Drawer",text:'Tertiary Fi in an ISTJ: a private moral ledger under a procedural exterior. It surfaces as the one client they will not take, the one joke that ends a friendship, the standing donation nobody hears about — commitments held for decades and explained, if pressed, as "just how I do things." The values are real; the vocabulary for them was never built.'},{kind:"the accusation",title:'"Selfish"',text:"The charge arrives sooner or later, usually mid-negotiation, usually from someone fluent in Fe. What is actually happening: Fi will not counterfeit agreement, and in a room that trades on visible accord, declining to fake it reads as defection. The refusal is not carelessness — an unfaked yes is the one currency Fi thinks worth paying anyone in, and it is priced accordingly."},{kind:"the misread",title:"Mistaken for No Opinion",text:"Weeks of amiable flexibility about restaurants, plans, and process — then a line is crossed and a verdict arrives whole, final, and non-negotiable. The tell that separates this from mere agreeableness: the position was settled long before the meeting, in private. Fe negotiates its stance in the room; Fi's stance predates the room, and the room is simply the last to find out."},{kind:"the wrong instrument",title:"The Mediation",text:"Ask Fi to chair a compromise between two parties it finds both partly wrong, and the instrument jams. It evaluates everything against one core tone and has no native operation for splitting the difference between other people's. It can do the job — through principle, at cost — while the table mistakes its silence for assent and its verdicts for stubbornness. This is Fe's home ground; Fi visits on foreign plates."}]};return{COL:t,SLOTS:l,CHARACTER:h,FEEDERS:d,SERIES:i,GRIP_T:u,COSTS:f,RECOVERY:p,VERIFY:y,HERO:g,ZONE_B:m,ZONE_C:w,ZONE_D:b,ZONE_E:v,ZONE_F:k}}export{I as l};
